import json,hashlib,platform,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from truss.model import load
from truss.solver import Solver
rows=json.loads((ROOT/'results/summary.json').read_text())
lines=['# Verified pilot results','', 'All values below are **author-checked within the frozen model**, not independent human review, global optimality, novelty, or physical certification. Baselines differ by profile and are named explicitly. Three seeds (17, 42, 2026), 120 DE generations, then structured local refinement were used for every row.','', '| Case / search | Before (lbm) | After (lbm) | After (kg) | Material saved | Before means |','|---|---:|---:|---:|---:|---|']
for r in rows:lines.append(f"| {r['case']} / {r['variant']} | {r['before_mass_lbm']:.6f} | {r['mass_lbm']:.6f} | {r['mass_kg']:.6f} | {r['savings_percent']:.4f}% | {'published feasible vector' if r['variant']=='reference' else 'feasible uniform maximum areas'} |")
lines+=['','The historical 10-bar baseline was retained. A small 25-bar reference improvement is a local result, not a literature record. Large tube-model percentages mainly measure savings over a deliberately heavy uniform design. They must not be described as improvements over published optima.','', '| Case | Best sizing-only mass | Best topology mass | Additional topology saving | Removed members |','|---|---:|---:|---:|---|']
for case in ['10bar','25bar']:
 size=next(r for r in rows if r['case']==case and r['variant']=='tube-sizing')['mass_lbm']; topo=next(r for r in rows if r['case']==case and r['variant']=='tube-topology')['mass_lbm'];rr=json.loads((ROOT/'results'/f'{case}-tube-topology-verification.json').read_text())['primary'];removed=[i+1 for i,a in enumerate(rr['member_areas']) if a==0]
 lines.append(f'| {case} | {size:.6f} | {topo:.6f} | {100*(1-topo/size):.4f}% | {removed} |')
lines+=['','These are comparisons of the best observed runs, not a proof that topology or a particular algorithm caused the full difference. Run variability matters.','', '| Case / search | Seed masses (lbm) | Max stress utilization | Max displacement utilization | Max Euler utilization |','|---|---|---:|---:|---:|']
maxeq=maxdiff=0
for r in rows:
 rep=json.loads((ROOT/'results'/f"{r['case']}-{r['variant']}-verification.json").read_text());q=rep['primary'];maxeq=max(maxeq,rep['independent']['equilibrium_relative']);maxdiff=max(maxdiff,max(rep['solver_relative_differences'].values()))
 lines.append(f"| {r['case']} / {r['variant']} | {', '.join(f'{v:.5f}' for v in r['run_masses_lbm'])} | {q['stress_utilization']:.8f} | {q['displacement_utilization']:.8f} | {q['buckling_utilization']:.8f} |")
lines+=['','Utilization <=1 is within the stated constraint. Euler utilization zero in reference rows means **not constrained**, not an infinite buckling margin.',f'Across the six winners, maximum independent free-equilibrium residual is {maxeq:.3g} relative to applied force; maximum normalized difference between solvers is {maxdiff:.3g}. Global force/moment balance and energy checks are retained in each verification JSON.','', '## Rendered comparisons','', '![10-bar tube](../results/10bar-tube-topology.png)','![25-bar tube](../results/25bar-tube-topology.png)','![10-bar reference](../results/10bar-reference.png)','![25-bar reference](../results/25bar-reference.png)','![Search trajectories](../results/search-traces.png)','', 'Red is tension and blue compression; the color bar shows signed force. The 10-bar plot annotates member number and force in kip. The spatial plot uses color to avoid unreadable labels; its exact signed forces are in the complete CSV schedules. Before/after panels share a force scale. Crossed members are not joined unless their endpoint node is shared.','', '## Reproduction and limits','', 'Run `python scripts/reproduce.py` in the pinned environment. `scripts/run_search.py` reconstructs the searches with recorded seeds, algorithm settings and model hashes. Unique evaluations, cache hits, infeasible evaluations, removed-member evaluations, local passes and timings are retained per run. Timings are descriptive: this was not an isolated performance experiment and other machine work may affect them. A clean-checkout run is recorded in `research/pilot/VERIFY.json`.','', 'Two published rows fail the frozen checks; see the literature audit and rejection tests. No source has been silently repaired. The 72-bar follow-on is surveyed only: its geometry and HBB-BC mass are transcribed, but feasibility and a discrete catalogue remain outside the verified portfolio.']
(ROOT/'docs/RESULTS.md').write_text('\n'.join(lines)+'\n')
# Model-only load perturbation diagnostics, explicitly outside the frozen inputs.
sens=[]
for case in ['10bar','25bar']:
 b=load(case); c=json.loads((ROOT/'results'/f'{case}-tube-topology-winner.json').read_text()); r=Solver(b,'tube-euler').evaluate(c['areas'])
 for lc in b['loads']:
  lc['nodal']=[[n,*[1.01*v for v in vals]] for n,*vals in lc['nodal']]
 q=Solver(b,'tube-euler').evaluate(c['areas']);sens.append(dict(case=case,diagnostic='all loads increased 1%; not frozen-frontier evaluation',linear_uniform_load_multiplier_limit=1/max(r['stress_utilization'],r['displacement_utilization'],r['buckling_utilization']),passes_1_percent_load_increase=q['valid'],max_utilization_after_increase=max(q['stress_utilization'],q['displacement_utilization'],q['buckling_utilization'])))
(ROOT/'results/sensitivity.json').write_text(json.dumps(sens,indent=2)+'\n')
assessment='''# Practical transfer and donor discovery potential

> **Historical (2026-10-20).** The recommendation below predates the launch: the project has
> been open to donated sessions since 2026-10-21, with a maintainer. Current status is in
> `DISCOVERY.md`; independent review of the solvers and benchmark transcription is still wanted.

The pilot is technically viable for donated computational research: a candidate is small, the objective is explicit, and a stranger can cheaply recompute every stored result with two implementations. The strongest immediate contribution is verification quality. Published-row discrepancies were detected before optimization, demonstrating useful outcomes even without a new minimum.

Practical transfer is **conceptual and methodological**. Discrete member sizing, explicit section inertia, load-path checks and grouped construction choices resemble real design decisions. The delivered model omits many governing engineering effects. No model here establishes real-world structural safety or suitability for construction. Review of full load combinations, self-weight, support/connection behavior, material/product data, global and local stability, nonlinear imperfections, manufacturing and physical tests would be required in a new engineering programme. An Euler factor of 1.5 is not a substitute for that programme.

Winning designs sit close to model constraints. The diagnostic below increases all prescribed loads by 1% without optimizing again; it is deliberately outside the frozen frontier. Its narrow linear load multipliers are not physical safety factors.

'''
for s in sens:assessment+=f"- {s['case']}: uniform linear load multiplier limit {s['linear_uniform_load_multiplier_limit']:.6f}; passes +1% load diagnostic: {s['passes_1_percent_load_increase']}.\n"
assessment+='''
Donor potential is moderate for methodological discovery and source auditing, low for claims of fundamental novelty from small classic benchmarks alone. Useful bounded tasks are independent external-solver reproduction, correction of inconsistent source vectors, more complete mechanism tests, a pinned discrete 72-bar extension, stronger local-search neighborhoods and lower-bound/optimality methods. The MILP literature motivates exact-bound work, but its assumptions must match the pilot's rank and buckling requirements. Three seeds are a pilot exploration, not a statistically convincing algorithm comparison.

The portfolio offers independent case/profile/seed units; replay is cheap and CPU-only. Limit submitted candidates to one verified improvement or a substantive negative finding per task, preserving the search budget and model digest. Duplicate tiny heuristic improvements should be batched for review. A volunteer can usually verify and report within a short session without rerunning the whole search. Additional compute is useful only after source fidelity and acceptance rules are trusted.

Douglas Colkitt is the confirmed maintainer. Review capacity remains unspecified; no public intake or hub consent is active. Before opening donations, obtain an independent review of both solver implementations and benchmark transcription, resolve or explicitly quarantine disputed baseline rows, measure a fresh donor rehearsal, and agree on a sustainable review rate. The current verification is author-checked; no claim of external acceptance is made. The repository contains concrete task cards, seeded task allocation, local handoffs, model hashes, replay commands and result packages, but no evidence yet of sustained multi-donor coordination or review throughput.
'''
(ROOT/'docs/ASSESSMENT.md').write_text(assessment)
frontier=dict(schema='discover-frontier/v0',statement='Six feasible local incumbent rows for two frozen truss models, with reference sizing and tube/Euler sizing/topology variants; every row recomputed by two implementations. Selected published baselines reproduce; no global optimum or physical safety claim.',status='Open to donated sessions since 2026-10-21; maintainer @Mister-Meeseeks. Author-checked; independent scientific review outstanding; frontier changes are a maintainer decision.',evidence_level=['author-checked'],claim_kind=['model'],scope='benchmarks/*bar.json v1.0.0 and LOCK.sha256.json; fixed node/member geometry, discrete group areas, float64 tolerances in docs/MODEL.md',assumptions=[dict(id='physical-transfer',statement='Ideal pin-jointed linear model; physical suitability is outside scope.',status='open',link='docs/MODEL.md'),dict(id='independent-review',statement='Both implementations authored in one session; external review remains outstanding.',status='open',link='discover/ledger.md')],review='discover/ledger.md',updated_on='2026-10-20',sources=['https://doi.org/10.1590/S1678-58782004000200008','https://pp.bme.hu/ci/article/download/460/217','https://doi.org/10.1007/s00158-022-03325-7'],table=dict(path='results/summary.json',key=['case','variant'],value='mass_lbm',direction='lower-is-better',object='object',check_row=['python3','scripts/check.py','{object}'],check_row_minutes=1,by='by',source='source',updated='updated'),reproduce='python3 scripts/reproduce.py',reproduce_full='python3 scripts/run_search.py --iterations 120 --seeds 17 42 2026 --output scratch/replay',reproduce_minutes=1,prerequisites=['Python >=3.12','pip install -r requirements.txt in a local virtual environment'],pinned_heads={'model_freeze':'b3024e9'},artifacts=[])
for path in sorted((ROOT/'benchmarks').glob('*.json'))+sorted((ROOT/'results').glob('*winner.json')):
 frontier['artifacts'].append(dict(path=str(path.relative_to(ROOT)),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
(ROOT/'discover/frontier.json').write_text(json.dumps(frontier,indent=2)+'\n')
print('Wrote results, transfer assessment, sensitivity diagnostic and frontier.')
